// Loop Unrolling Example (Factor 4)
// Reduces loop overhead and increases Instruction Level Parallelism (ILP)

void scale_array(double* data, int N, double factor) {
    int i = 0;
    const int UNROLL = 4;

    // Core unrolled loop
    for (i = 0; i <= N - UNROLL; i += UNROLL) {
        data[i]   *= factor;
        data[i+1] *= factor;
        data[i+2] *= factor;
        data[i+3] *= factor;
    }

    // Epilogue (handling remainder)
    for (; i < N; ++i) {
        data[i] *= factor;
    }
}

// Loop Reassociation Example (Accumulation)
// Breaking serial dependency chains to allow parallel execution (Vectorization)

float parallel_sum(const float* V, int N) {
    // Standard approach: sum += V[i] (High dependency)

    // Reassociated approach: Two accumulators S0, S1
    float S0 = 0.0f;
    float S1 = 0.0f;

    for (int i = 0; i < N; i += 2) {
        S0 += V[i];
        S1 += V[i+1];
    }
    return S0 + S1; // Final reduction
}
